import type { FC } from 'react';
import { useEffect, useRef, useState } from 'react';
import { toast } from 'sonner';
import { UploadCloud, X, ImageIcon } from 'lucide-react';
import { formatBytes } from '@/lib/image/convert';

interface UploadBoxProps {
  file: File | null;
  onSelect: (file: File) => void;
  onClear: () => void;
}

const MAX_BYTES = 25 * 1024 * 1024;

const UploadBox: FC<UploadBoxProps> = ({ file, onSelect, onClear }) => {
  const inputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [previewFailed, setPreviewFailed] = useState(false);

  useEffect(() => {
    if (!file) {
      setPreviewUrl(null);
      return;
    }
    setPreviewFailed(false);
    const url = URL.createObjectURL(file);
    setPreviewUrl(url);
    return () => URL.revokeObjectURL(url);
  }, [file]);

  const handleFiles = (files: FileList | null) => {
    const picked = files?.[0];
    if (!picked) return;
    if (picked.size > MAX_BYTES) {
      toast.error(`Image is too large (max ${formatBytes(MAX_BYTES)})`);
      return;
    }
    onSelect(picked);
  };

  if (file) {
    return (
      <div className="glass-panel hover:border-border p-4 flex items-center gap-4">
        <div className="w-16 h-16 rounded-lg overflow-hidden border border-border bg-background/50 shrink-0 flex items-center justify-center">
          {previewUrl && !previewFailed ? (
            <img
              src={previewUrl}
              alt=""
              onError={() => setPreviewFailed(true)}
              className="w-full h-full object-cover"
            />
          ) : (
            <ImageIcon className="w-6 h-6 text-muted-foreground" />
          )}
        </div>
        <div className="flex-1 min-w-0">
          <p className="text-sm font-medium text-foreground truncate">{file.name}</p>
          <p className="text-xs text-muted-foreground">
            {formatBytes(file.size)} · {file.type || 'unknown type'}
          </p>
        </div>
        <button
          type="button"
          onClick={onClear}
          aria-label="Remove image"
          className="shrink-0 p-2 rounded-full text-muted-foreground hover:text-accent hover:bg-accent/10 transition-colors"
        >
          <X className="w-4 h-4" />
        </button>
      </div>
    );
  }

  return (
    <div
      onClick={() => inputRef.current?.click()}
      onDragOver={(e) => {
        e.preventDefault();
        setIsDragging(true);
      }}
      onDragLeave={() => setIsDragging(false)}
      onDrop={(e) => {
        e.preventDefault();
        setIsDragging(false);
        handleFiles(e.dataTransfer.files);
      }}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') inputRef.current?.click();
      }}
      className={`glass-panel flex flex-col items-center justify-center gap-3 py-14 px-6 text-center cursor-pointer transition-colors ${
        isDragging ? 'border-accent/60 bg-accent/5' : 'hover:border-border'
      }`}
    >
      <input
        ref={inputRef}
        type="file"
        accept="image/*"
        className="hidden"
        onChange={(e) => handleFiles(e.target.files)}
      />
      <UploadCloud className="w-8 h-8 text-muted-foreground/50" />
      <div>
        <p className="text-sm font-medium text-foreground">Drop an image here, or click to browse</p>
        <p className="text-xs text-muted-foreground mt-1">PNG, JPEG, WebP, BMP, GIF, and more</p>
      </div>
    </div>
  );
};

export default UploadBox;
