import type { FC } from 'react';
import { useEffect, useState } from 'react';
import { toast } from 'sonner';
import { Download, Copy, Check } from 'lucide-react';
import { formatBytes } from '@/lib/image/convert';
import { getFormatMeta, type ImageOutputFormat } from '@/lib/image/types';

interface ConversionResultProps {
  blob: Blob | null;
  originalSize: number;
  format: ImageOutputFormat;
  fileBaseName: string;
  isConverting: boolean;
  error: string | null;
}

const buttonBase =
  'inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium transition-colors disabled:opacity-40 disabled:cursor-not-allowed';

// Faint checkerboard so transparent regions (PNG/WebP/ICO output) read as transparent, not black.
const checkerboardStyle = {
  backgroundImage:
    'linear-gradient(45deg, hsl(var(--border)) 25%, transparent 25%), linear-gradient(-45deg, hsl(var(--border)) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, hsl(var(--border)) 75%), linear-gradient(-45deg, transparent 75%, hsl(var(--border)) 75%)',
  backgroundSize: '10px 10px',
  backgroundPosition: '0 0, 0 5px, 5px -5px, -5px 0px',
};

const ConversionResult: FC<ConversionResultProps> = ({
  blob,
  originalSize,
  format,
  fileBaseName,
  isConverting,
  error,
}) => {
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const meta = getFormatMeta(format);

  useEffect(() => {
    if (!blob) {
      setPreviewUrl(null);
      return;
    }
    const url = URL.createObjectURL(blob);
    setPreviewUrl(url);
    return () => URL.revokeObjectURL(url);
  }, [blob]);

  const handleDownload = () => {
    if (!blob) return;
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${fileBaseName}.${meta.extension}`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  };

  const handleCopy = async () => {
    if (!blob) return;
    try {
      await navigator.clipboard.write([new ClipboardItem({ [blob.type]: blob })]);
      setCopied(true);
      toast.success('Copied converted image');
      window.setTimeout(() => setCopied(false), 1500);
    } catch {
      toast.error('Copy failed — try downloading instead');
    }
  };

  if (error) {
    return (
      <div className="glass-panel p-6 text-sm text-destructive" role="alert">
        {error}
      </div>
    );
  }

  if (!blob || !previewUrl) {
    return (
      <div className="glass-panel p-6 flex items-center justify-center text-sm text-muted-foreground min-h-[104px]">
        {isConverting ? 'Converting…' : 'Upload an image to see the converted result'}
      </div>
    );
  }

  const delta = blob.size - originalSize;
  const pct = originalSize > 0 ? Math.round((delta / originalSize) * 100) : 0;

  return (
    <div className="glass-panel hover:border-border p-4">
      <div className="flex items-center gap-4 mb-4">
        <div
          className="w-16 h-16 rounded-lg overflow-hidden border border-border shrink-0"
          style={checkerboardStyle}
        >
          <img src={previewUrl} alt="Converted preview" className="w-full h-full object-contain" />
        </div>
        <div className="flex-1 min-w-0">
          <p className="text-sm font-medium text-foreground">
            {meta.label} · {formatBytes(blob.size)}
          </p>
          <p className={`text-xs ${delta <= 0 ? 'text-accent' : 'text-muted-foreground'}`}>
            {delta === 0
              ? 'Same size as original'
              : `${delta > 0 ? '+' : ''}${pct}% vs original (${formatBytes(originalSize)})`}
          </p>
        </div>
      </div>

      <div className="flex flex-wrap gap-3">
        <button
          type="button"
          onClick={handleDownload}
          className={`${buttonBase} bg-accent text-accent-foreground hover:bg-accent/90`}
        >
          <Download className="w-4 h-4" />
          Download {meta.label}
        </button>
        <button
          type="button"
          onClick={handleCopy}
          className={`${buttonBase} border border-border text-foreground/80 hover:text-foreground hover:border-accent/40`}
        >
          {copied ? <Check className="w-4 h-4 text-accent" /> : <Copy className="w-4 h-4" />}
          Copy Image
        </button>
      </div>
    </div>
  );
};

export default ConversionResult;
