import type { FC } from 'react';
import { useEffect, useState } from 'react';
import ToolLayout from '@/components/tools/ToolLayout';
import PillGroup from '@/components/tools/PillGroup';
import UploadBox from '@/components/tools/image-converter/UploadBox';
import QualitySlider from '@/components/tools/image-converter/QualitySlider';
import ConversionResult from '@/components/tools/image-converter/ConversionResult';
import { usePersistentState } from '@/hooks/usePersistentState';
import { useDebouncedValue } from '@/hooks/useDebouncedValue';
import { canEncodeWebp, convertImage, loadImageToCanvas } from '@/lib/image/convert';
import { IMAGE_OUTPUT_FORMATS, getFormatMeta, type ImageOutputFormat } from '@/lib/image/types';

const ImageConverter: FC = () => {
  const [file, setFile] = usePersistentState<File | null>('image-converter:file', null);
  const [format, setFormat] = usePersistentState<ImageOutputFormat>('image-converter:format', 'png');
  const [quality, setQuality] = usePersistentState<number>('image-converter:quality', 85);

  const [webpSupported, setWebpSupported] = useState(true);
  const [sourceCanvas, setSourceCanvas] = useState<HTMLCanvasElement | null>(null);
  const [convertedBlob, setConvertedBlob] = useState<Blob | null>(null);
  const [isConverting, setIsConverting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const debouncedQuality = useDebouncedValue(quality, 150);

  useEffect(() => {
    canEncodeWebp().then(setWebpSupported);
  }, []);

  // Decode the source file into a canvas whenever it changes.
  useEffect(() => {
    let ignore = false;
    if (!file) {
      setSourceCanvas(null);
      setError(null);
      return;
    }
    setError(null);
    loadImageToCanvas(file)
      .then((canvas) => {
        if (!ignore) setSourceCanvas(canvas);
      })
      .catch((err: Error) => {
        if (!ignore) {
          setError(err.message || "This file couldn't be read as an image");
          setSourceCanvas(null);
        }
      });
    return () => {
      ignore = true;
    };
  }, [file]);

  // Re-encode whenever the decoded image, target format, or (debounced) quality changes.
  useEffect(() => {
    let ignore = false;
    if (!sourceCanvas) {
      setConvertedBlob(null);
      return;
    }
    setIsConverting(true);
    convertImage(sourceCanvas, format, debouncedQuality)
      .then((blob) => {
        if (!ignore) {
          setConvertedBlob(blob);
          setIsConverting(false);
        }
      })
      .catch((err: Error) => {
        if (!ignore) {
          setError(err.message || 'Conversion failed');
          setIsConverting(false);
        }
      });
    return () => {
      ignore = true;
    };
  }, [sourceCanvas, format, debouncedQuality]);

  const formatOptions = IMAGE_OUTPUT_FORMATS.filter((f) => f.id !== 'webp' || webpSupported).map((f) => ({
    value: f.id,
    label: f.label,
  }));

  const selectedMeta = getFormatMeta(format);
  const fileBaseName = file ? file.name.replace(/\.[^./]+$/, '') || 'image' : 'image';

  return (
    <ToolLayout
      title="Image Type Converter"
      description="Convert images between PNG, JPEG, WebP, BMP, and ICO — entirely in your browser, nothing is uploaded anywhere."
    >
      <div className="max-w-2xl mx-auto space-y-6">
        <UploadBox file={file} onSelect={setFile} onClear={() => setFile(null)} />

        {file && (
          <>
            <div>
              <h2 className="text-sm font-medium text-muted-foreground mb-3">Convert to</h2>
              <PillGroup
                aria-label="Output format"
                options={formatOptions}
                value={format}
                onChange={setFormat}
              />
              <p className="text-xs text-muted-foreground mt-2 leading-relaxed">{selectedMeta.description}</p>
            </div>

            {selectedMeta.supportsQuality && <QualitySlider quality={quality} onChange={setQuality} />}

            <ConversionResult
              blob={convertedBlob}
              originalSize={file.size}
              format={format}
              fileBaseName={fileBaseName}
              isConverting={isConverting}
              error={error}
            />
          </>
        )}
      </div>
    </ToolLayout>
  );
};

export default ImageConverter;
